export const QUIZ_ITEMS = [
  { id: "1765", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام ابن تيمية؟ وما أبرز مؤلفاته؟", answer: "هو شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني الحنبلي (661-728هـ). وُلد في حرّان وعاش في دمشق. أبرز مؤلفاته: «درء تعارض العقل والنقل»، «منهاج السنة النبوية»، «الفتاوى الكبرى»، «الاستقامة»، «اقتضاء الصراط المستقيم». اشتُهر بالتجديد في مسائل العقيدة والرد على الفلسفة الكلامية وعلى الغلو والبدع.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1766", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما الفرق بين «الإسناد» و«المتن» في علم الحديث؟", answer: "الإسناد (السند): هو سلسلة الرواة الذين نقلوا الحديث من راوٍ إلى آخر حتى وصل إلى النبي ﷺ. والمتن: هو نص الحديث ومضمونه الذي قاله النبي ﷺ أو فعله. الحكم على الحديث صحةً وضعفاً يعتمد في الأساس على دراسة الإسناد (رجاله وعلله)، ثم دراسة المتن للكشف عن الشذوذ والنكارة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1767", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام النووي؟ وما أبرز مؤلفاته؟", answer: "هو الإمام يحيى بن شرف النووي الشافعي (631-676هـ)، من أكبر علماء الإسلام وأتقاهم. وُلد في نوى بسوريا. أبرز مؤلفاته: «رياض الصالحين» و«الأذكار» و«المنهاج في شرح صحيح مسلم» (المعروف بشرح النووي) و«المجموع شرح المهذب» و«الأربعون النووية». توفي وعمره 45 سنة لكنه ترك إرثاً علمياً ضخماً يُدرَّس حتى اليوم.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1768", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما المذاهب الفقهية الأربعة المعتمدة؟ ومن مؤسسوها؟", answer: "المذاهب الفقهية الأربعة: 1) الحنفي — مؤسسه الإمام أبو حنيفة النعمان (80-150هـ). 2) المالكي — مؤسسه الإمام مالك بن أنس (93-179هـ). 3) الشافعي — مؤسسه الإمام محمد بن إدريس الشافعي (150-204هـ). 4) الحنبلي — مؤسسه الإمام أحمد بن حنبل (164-241هـ). كل مذهب له منهجه في الاجتهاد والاستدلال، ويُعبّر عن فهم دقيق للنصوص الشرعية، والخلاف بينها رحمة وتوسعة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1769", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "سهل", question: "من هو الإمام البخاري وما اسمه الكامل؟", answer: "هو محمد بن إسماعيل البخاري (194-256هـ)، وُلد في بخارى بأوزبكستان. مؤلف أصح كتاب بعد كتاب الله وهو الجامع الصحيح المعروف بصحيح البخاري الذي يحتوي على 7563 حديثاً مكرراً، وهو إمام علماء الحديث.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1770", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "في أي قرن عاش الإمام الغزالي وما لقبه الشهير؟", answer: "عاش أبو حامد الغزالي (450-505هـ) في القرن الخامس الهجري. لقّبه العلماء بـ«حجة الإسلام» لعلمه الغزير ومواقفه الدفاعية عن الإسلام. وُلد في طوس بخراسان (إيران)، وأشهر كتبه إحياء علوم الدين.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1771", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "من هو ابن تيمية وأين وُلد وتوفي؟", answer: "هو أحمد بن عبد الحليم ابن تيمية الحراني (661-728هـ). وُلد في حران (جنوب تركيا) وتوفي في سجن دمشق. عالم حنبلي موسوعي في الفقه والعقيدة والتفسير. أشهر طلابه ابن قيم الجوزية، وأشهر كتبه الفتاوى الكبرى ومنهاج السنة.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1772", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "ما اسم الإمام الشافعي كاملاً وأين وُلد؟", answer: "هو محمد بن إدريس الشافعي القرشي (150-204هـ). وُلد في غزة (فلسطين) وتوفي في مصر. مؤسس المذهب الشافعي وصاحب كتاب الرسالة أول مصنَّف في أصول الفقه. حفظ القرآن في سن السابعة وحفظ الموطأ في سن العاشرة.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1773", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "من هو ابن حجر العسقلاني وما أهم مؤلفاته في الحديث؟", answer: "هو أحمد بن علي بن حجر العسقلاني (773-852هـ)، مصري الأصل من عسقلان. أمير المؤمنين في الحديث. أشهر مؤلفاته: فتح الباري شرح صحيح البخاري (13 مجلداً)، والإصابة في تمييز الصحابة، وتقريب التهذيب. استغرق فتح الباري منه 25 عاماً.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1774", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "ما مدينة الميلاد والوفاة لكلٍّ من الأئمة الأربعة؟", answer: "أبو حنيفة: وُلد في الكوفة وتوفي في بغداد. مالك بن أنس: وُلد وتوفي في المدينة المنورة. الشافعي: وُلد في غزة وتوفي في الفسطاط (القاهرة). أحمد بن حنبل: وُلد وتوفي في بغداد.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1775", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "من هو ابن قيم الجوزية وما علاقته بابن تيمية؟", answer: "هو محمد بن أبي بكر ابن قيّم الجوزية (691-751هـ)، من دمشق. لازم شيخه ابن تيمية نحو 17 عاماً وسجن معه في قلعة دمشق. أشهر كتبه: زاد المعاد، إغاثة اللهفان، مدارج السالكين. أتم كثيراً مما بدأه ابن تيمية.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1776", section: "القرآن الكريم", category: "السور", level: "سهل", question: "كم عدد سور القرآن الكريم؟", answer: "114 سورة — عدد سور القرآن الكريم، بين أقصرها (الكوثر) وأطولها (البقرة).", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1777", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما السورة التي تُسمى أم الكتاب وأم القرآن؟", answer: "سورة الفاتحة — تُسمى أم الكتاب وأم القرآن، وتُقرأ في كل ركعة من الصلوات.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1778", section: "القرآن الكريم", category: "الآيات", level: "متوسط", question: "في أي سورة توجد آية الكرسي؟", answer: "سورة البقرة — السورة التي فيها آية الكرسي (255)، أعظم آية في كتاب الله.", explanation: "يُستفاد منه في باب الآيات. يُستفاد منه في باب الآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1779", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما السورة الوحيدة التي لا تبدأ بالبسملة؟", answer: "سورة التوبة — السورة الوحيدة التي لا تبدأ بالبسملة لاشتمالها على براءة من المشركين.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1780", section: "القرآن الكريم", category: "السور", level: "صعب", question: "في أي سورة ذُكرت البسملة مرتين؟", answer: "سورة النمل — السورة الوحيدة التي ذُكرت فيها البسملة مرتين (في أولها وفي قصة سليمان).", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1781", section: "القرآن الكريم", category: "النزول", level: "متوسط", question: "ما آخر سورة نزلت كاملةً على النبي ﷺ؟", answer: "سورة النصر — آخر سورة نزلت كاملةً، وفيها بشارة بفتح مكة ودخول الناس في الإسلام.", explanation: "يُستفاد منه في باب النزول. يُستفاد منه في باب النزول مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1782", section: "القرآن الكريم", category: "الجمع", level: "متوسط", question: "من الصحابي الذي أشرف على جمع القرآن في عهد أبي بكر الصديق؟", answer: "زيد بن ثابت رضي الله عنه — الصحابي الذي أشرف على جمع القرآن في مصحف واحد في عهد أبي بكر.", explanation: "يُستفاد منه في باب الجمع. يُستفاد منه في باب الجمع مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1783", section: "القرآن الكريم", category: "الجمع", level: "متوسط", question: "في عهد أي خليفة وُحِّدت نسخة القرآن ووُزِّعت على الأمصار؟", answer: "عثمان بن عفان رضي الله عنه — الخليفة الذي وُحّدت في عهده نسخة القرآن ووُزّعت على الأمصار.", explanation: "يُستفاد منه في باب الجمع. يُستفاد منه في باب الجمع مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1784", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما السورة التي تحكي قصة أصحاب الكهف؟", answer: "سورة الكهف — السورة التي تحكي قصة أصحاب الكهف وفيها ذكر ذي القرنين.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1785", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما السورة التي سُميت بأسماء نبي من الأنبياء وفيها قصته كاملة؟", answer: "سورة يوسف — السورة الوحيدة التي سُميت باسم نبي وفيها قصته كاملةً من البداية للنهاية.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1786", section: "القرآن الكريم", category: "الآيات", level: "صعب", question: "كم مرة ذُكر اسم النبي محمد ﷺ في القرآن الكريم؟", answer: "أربع مرات: آل عمران (144)، والأحزاب (40)، ومحمد (2)، والفتح (29) — وذُكر باسم «أحمد» مرة واحدة في الصف (6)", explanation: "يُستفاد منه في باب الآيات. يُستفاد منه في باب الآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1787", section: "القرآن الكريم", category: "السور", level: "صعب", question: "كم عدد السور المدنية في القرآن الكريم تقريباً؟", answer: "28 سورة — عدد السور المدنية تقريباً في القرآن، وما عداها فمكية أو فيها آيات مدنية.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1788", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما السورة التي اشتهرت تسميتها بقلب القرآن؟", answer: "سورة يس — وهذه تسمية مشتهرة على الألسنة، والحديث الوارد فيها «إن لكل شيء قلباً وقلب القرآن يس» لا يصح: قال أبو حاتم الرازي: باطل لا أصل له، وحكم عليه الألباني بالوضع في ضعيف الترمذي والسلسلة الضعيفة (5870)، وقال ابن باز: ليس له أصل", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1789", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما السور التي افتُتحت بالحروف المقطعة (الم)؟", answer: "ست سور: البقرة، وآل عمران، والعنكبوت، والروم، ولقمان، والسجدة", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1790", section: "القرآن الكريم", category: "السور والآيات", level: "سهل", question: "ما السورة التي سُمّيت باسم الجن؟", answer: "سورة الجن (السورة الثانية والسبعون). ولا يعني ذلك انفرادها بذكرهم، فقد ورد لفظ «الجن» في إحدى عشرة سورة: الأنعام والأعراف والإسراء والكهف والنمل وسبأ وفصلت والأحقاف والذاريات والرحمن والجن", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1791", section: "القرآن الكريم", category: "السور والآيات", level: "سهل", question: "ما عدد آيات سورة الفاتحة؟", answer: "سبع آيات، ومأخذ ذلك قوله تعالى: ﴿وَلَقَدْ آتَيْنَاكَ سَبْعًا مِّنَ الْمَثَانِي وَالْقُرْآنَ الْعَظِيمَ﴾ [الحجر: 87]. والعدد سبع لا خلاف فيه، وإنما الخلاف في وجه العدّ: فمن عدّ البسملة آيةً منها (وهو مذهب الشافعية وعدّ أهل مكة والكوفة، وعليه المصحف المتداول) جعل ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ...﴾ آيةً واحدة، ومن لم يعدّها منها (وهو مذهب المالكية والحنفية وعدّ أهل المدينة والبصرة والشام) عدّ ما بعدها آيتين؛ فيتفق العدد على القولين", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1792", section: "القرآن الكريم", category: "نزول القرآن", level: "متوسط", question: "ما أول كلمة نزلت من القرآن الكريم؟", answer: "«اقرأ»؛ فأول ما نزل من القرآن صدر سورة العلق: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الْأَكْرَمُ * الَّذِي عَلَّمَ بِالْقَلَمِ * عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ﴾ [العلق: 1-5]، كما في حديث عائشة رضي الله عنها في بدء الوحي — رواه البخاري في أول صحيحه ومسلم. وهذا في أول ما نزل مطلقًا؛ وأما أول ما نزل بعد فترة الوحي فصدر سورة المدثر", explanation: "يُستفاد منه في باب نزول القرآن. يُستفاد منه في باب نزول القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1793", section: "القرآن الكريم", category: "نزول القرآن", level: "متوسط", question: "من الذي تولّى نسخ المصاحف في عهد عثمان بن عفان رضي الله عنه؟", answer: "زيد بن ثابت رضي الله عنه، وكان على رأس اللجنة ومعه نفرٌ من الصحابة كلَّفهم عثمان رضي الله عنه بالنسخ من الصحف التي كانت عند أم المؤمنين حفصة؛ وعثمان هو الذي أمر بالنسخ وأرسل المصاحف إلى الأمصار", explanation: "يُستفاد منه في باب نزول القرآن. يُستفاد منه في باب نزول القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1794", section: "القرآن الكريم", category: "نزول القرآن", level: "متوسط", question: "في كم يوم خُلقت السماوات والأرض كما ذكر القرآن الكريم؟", answer: "في ستة أيام، وقد تكرّر ذلك في سبعة مواضع من القرآن: الأعراف 54، ويونس 3، وهود 7، والفرقان 59، والسجدة 4، وق 38، والحديد 4؛ قال تعالى: ﴿إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ﴾ [الأعراف: 54]", explanation: "يُستفاد منه في باب نزول القرآن. يُستفاد منه في باب نزول القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1795", section: "القرآن الكريم", category: "السور والآيات", level: "متوسط", question: "ما السورة التي فيها قصة ذي القرنين؟", answer: "سورة الكهف — السورة التي فيها قصة ذي القرنين وبناء الردم حابس يأجوج ومأجوج.", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1796", section: "القرآن الكريم", category: "السور والآيات", level: "متوسط", question: "ما السورة التي فيها ذكر أصحاب الأخدود؟", answer: "سورة البروج — السورة التي فيها ذكر أصحاب الأخدود الذين أُحرقوا على دينهم.", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1797", section: "القرآن الكريم", category: "السور والآيات", level: "سهل", question: "ما اسم السورة التي نزلت في أبي لهب وزوجته؟", answer: "سورة المسد (تبّت يدا أبي لهب) — السورة التي نزلت في أبي لهب وزوجته أم جميل.", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1798", section: "القرآن الكريم", category: "السور والآيات", level: "متوسط", question: "ما اسم مجموعة السور التي تبدأ بـ (حم)؟", answer: "الحواميم السبع، وهي سبع سور متتالية في ترتيب المصحف من رقم 40 إلى 46: غافر، وفصلت، والشورى (وفيها ﴿حم * عسق﴾)، والزخرف، والدخان، والجاثية، والأحقاف", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1799", section: "القرآن الكريم", category: "الأنبياء في القرآن", level: "متوسط", question: "كم مرة ذُكر اسم عيسى عليه السلام في القرآن الكريم؟", answer: "خمساً وعشرين مرة، موزّعة على إحدى عشرة سورة. وهذا في ذكره باسمه «عيسى» خاصةً؛ فقد ذُكر أيضاً بأوصافه وألقابه في مواضع أخرى مثل «المسيح» و«ابن مريم» و«كلمته» و«روح منه»", explanation: "يُستفاد منه في باب الأنبياء في القرآن. يُستفاد منه في باب الأنبياء في القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1800", section: "القرآن الكريم", category: "السور والآيات", level: "متوسط", question: "ما معنى تسمية الفاتحة بـ (المثاني)؟", answer: "أصل التسمية من قوله تعالى: ﴿وَلَقَدْ آتَيْنَاكَ سَبْعًا مِّنَ الْمَثَانِي وَالْقُرْآنَ الْعَظِيمَ﴾ [الحجر: 87]. وأشهر ما قيل في وجهها: أنها تُثنى أي تُكرر في كل ركعة من الصلاة، وهو أحد أقوال أهل العلم في المسألة", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1801", section: "القرآن الكريم", category: "السور والآيات", level: "سهل", question: "ما أطول آية في القرآن الكريم؟", answer: "آية الدَّين، وهي الآية 282 من سورة البقرة، ومطلعها: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰ أَجَلٍ مُّسَمًّى فَاكْتُبُوهُ﴾. وسُمّيت بذلك لأنها أطول آية في كتاب الله وفيها أحكام توثيق الدَّين بالكتابة والإشهاد والرهن", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1802", section: "القرآن الكريم", category: "السور والآيات", level: "صعب", question: "ما آخر آية نزلت من القرآن الكريم على الراجح؟", answer: "قوله تعالى: ﴿وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ﴾ [البقرة: 281]", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1803", section: "القرآن الكريم", category: "فضائل السور", level: "متوسط", question: "ما السورتان اللتان يُستحب قراءتهما في فجر الجمعة؟", answer: "سورة السجدة في الركعة الأولى، وسورة الإنسان في الثانية؛ ثبت ذلك من فعله ﷺ في حديث أبي هريرة رضي الله عنه: «كان النبي ﷺ يقرأ في صلاة الفجر يوم الجمعة: الم تنزيل السجدة، وهل أتى على الإنسان» متفق عليه. وهو استحباب لا وجوب، وقصده اتّباع السنة لا السجدة وحدها؛ وقد كره بعض أهل العلم — منهم الإمام مالك — المداومة عليهما خشية أن يظن العامة وجوبهما", explanation: "يُستفاد منه في باب فضائل السور. يُستفاد منه في باب فضائل السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1804", section: "القرآن الكريم", category: "علوم القرآن", level: "صعب", question: "كم مرة تقريباً ذُكر لفظ الجلالة (الله) في القرآن الكريم؟", answer: "المشهور المتداول في كتب الإحصاء القرآني نحو 2699 مرة، ولا يصح الجزم برقم واحد؛ فالأعداد تختلف باختلاف طريقة العدّ: هل تُحسب الصور المسبوقة بحرف (والله، بالله، لله، ولله، تالله، فالله، فلله) مع اللفظ المجرد أم لا، وهل يُعدّ «اللهم» منه. وبعدٍّ آليّ مباشر على نص المصحف: ورد اللفظ مجرداً «الله» 2265 مرة، ويبلغ المجموع مع سائر صوره المسبوقة بحرف نحو 2800 موضع", explanation: "يُستفاد منه في باب علوم القرآن. يُستفاد منه في باب علوم القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1805", section: "القرآن الكريم", category: "علوم القرآن", level: "متوسط", question: "ما الفرق بين السورة المكية والمدنية؟", answer: "المعتمد عند جمهور أهل علوم القرآن اعتبار زمن النزول: فالمكي ما نزل قبل الهجرة ولو نزل بغير مكة، والمدني ما نزل بعد الهجرة ولو نزل بمكة؛ ولذلك عُدَّ ما نزل عام الفتح بمكة وما نزل بعرفة في حجة الوداع مدنيًّا. وثمّ اصطلاحان آخران أقلّ اعتبارًا: اعتبار مكان النزول (فما نزل بمكة وما حولها مكي، وما نزل بالمدينة وما حولها مدني)، واعتبار المخاطَبين (فما صُدِّر بـ«يا أيها الناس» مكي، وما صُدِّر بـ«يا أيها الذين آمنوا» مدني) — وهذان لا يطّردان", explanation: "يُستفاد منه في باب علوم القرآن. يُستفاد منه في باب علوم القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1806", section: "القرآن الكريم", category: "علوم القرآن", level: "صعب", question: "ما الدعاء القرآني الذي كان النبي ﷺ يُكثر منه؟", answer: "قوله تعالى: ﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾ [البقرة: 201]؛ ففي حديث أنس بن مالك رضي الله عنه أن أكثر دعاء النبي ﷺ كان بهذه الدعوة — متفق عليه", explanation: "يُستفاد منه في باب علوم القرآن. يُستفاد منه في باب علوم القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1807", section: "القرآن الكريم", category: "السور والآيات", level: "صعب", question: "ما أشهر سورة مدنية في الجزء الأخير (جزء عمّ)؟", answer: "سورة النصر، وهي مدنية باتفاق؛ نزلت في أواخر حياته ﷺ. ولا يصح وصفها بأنها المدنية الوحيدة في جزء عمّ، فقد وُصفت بالمدنية أيضاً — على ما جرى عليه المصحف المتداول وبيانات المصحف المعتمدة في المنصة — سورتا البيّنة والزلزلة، وكلتاهما مختلَف في نزولها بين أهل العلم؛ كما اختُلف في المطفِّفين والفلق والناس", explanation: "يُستفاد منه في باب السور والآيات. يُستفاد منه في باب السور والآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1808", section: "القرآن الكريم", category: "علوم القرآن", level: "صعب", question: "ما المعاملة المحرَّمة التي ورد لفظها في القرآن الكريم ثماني مرات؟", answer: "الرِّبا؛ ورد لفظه ثماني مرات: سبعاً معرَّفاً بـ«ال» في البقرة 275 (ثلاث مرات) و276 و278، وآل عمران 130، والنساء 161، ومرةً نكرةً في الروم 39: ﴿وَمَا آتَيْتُم مِّن رِّبًا لِّيَرْبُوَ فِي أَمْوَالِ النَّاسِ فَلَا يَرْبُو عِندَ اللَّهِ﴾. وموضع التصريح بتحريمه قوله تعالى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ [البقرة: 275]", explanation: "يُستفاد منه في باب علوم القرآن. يُستفاد منه في باب علوم القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1809", section: "القرآن الكريم", category: "السور", level: "سهل", question: "ما أول سورة في ترتيب المصحف؟", answer: "سورة الفاتحة، ولذلك سُميت «فاتحة الكتاب». ولا يلزم من كونها أول المصحف أن تكون أول ما نزل، فإن أول ما نزل من القرآن صدر سورة العلق", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1810", section: "القرآن الكريم", category: "السور", level: "سهل", question: "ما آخر سورة في القرآن؟", answer: "سورة الناس — آخر سورة في ترتيب المصحف، وهي من المعوذات.  — يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1811", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما أول ما نزل من القرآن؟", answer: "أول خمس آيات من سورة العلق (اقرأ) — أول ما نزل من القرآن في غار حراء.", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1812", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما آخر ما نزل من القرآن؟", answer: "آية ﴿وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ﴾ في قول أكثر العلماء", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1813", section: "القرآن الكريم", category: "السور", level: "متوسط", question: "ما أطول السور المدنية؟", answer: "البقرة وآل عمران والنساء والمائدة والأنفال والتوبة. والمدنيّ في اصطلاح أكثر أهل العلم ما نزل بعد الهجرة ولو نزل بمكة، لا ما نزل بالمدينة فحسب", explanation: "يُستفاد منه في باب السور. يُستفاد منه في باب السور مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1814", section: "القرآن الكريم", category: "الآيات", level: "سهل", question: "ما أعظم آية في القرآن؟", answer: "آية الكرسي [البقرة: 255]، ومطلعها: ﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ﴾؛ لحديث أُبيّ بن كعب رضي الله عنه أن النبي ﷺ سأله: «أتدري أيُّ آية من كتاب الله معك أعظم؟» فقال: آية الكرسي، فضرب في صدره وقال: «ليَهْنِكَ العلمُ أبا المنذر» (رواه مسلم)", explanation: "يُستفاد منه في باب الآيات. يُستفاد منه في باب الآيات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

